begin;
create extension if not exists pgtap;
select no_plan();
set local natillera.civil_today='2026-10-20';
insert into auth.users(id,aud,role,email,created_at,updated_at)
values('a2010000-0000-4000-8000-000000000001','authenticated','authenticated','cash-location-unit@example.test',now(),now());
insert into public.workspaces(id,name)values('a2010000-0000-4000-8000-000000000002','Synthetic cash location');
insert into public.workspace_users(workspace_id,user_id,role)values('a2010000-0000-4000-8000-000000000002','a2010000-0000-4000-8000-000000000001','admin');
insert into public.cycles(id,workspace_id,year,name,starts_on,closes_on,status)
values('a2010000-0000-4000-8000-000000000003','a2010000-0000-4000-8000-000000000002',2026,'Synthetic cash location','2026-01-01','2026-12-05','active');
insert into public.members(id,workspace_id,display_name)values('a2010000-0000-4000-8000-000000000004','a2010000-0000-4000-8000-000000000002','Synthetic debtor');
insert into public.cycle_members(id,workspace_id,cycle_id,member_id,monthly_quota)
values('a2010000-0000-4000-8000-000000000005','a2010000-0000-4000-8000-000000000002','a2010000-0000-4000-8000-000000000003','a2010000-0000-4000-8000-000000000004',10000);
set local request.jwt.claim.sub='a2010000-0000-4000-8000-000000000001';
set local role authenticated;
select public.create_bank_account('a2010000-0000-4000-8000-000000000003','Synthetic location bank','','');
select public.record_bank_opening('a2010000-0000-4000-8000-000000000003',(select id from bank_accounts where display_name='Synthetic location bank'),'location-opening','2026-01-01',1000000,'Synthetic opening');
select public.record_internal_liquidity_transfer('a2010000-0000-4000-8000-000000000003','location-initial-cash','2026-01-01','bank',(select id from bank_accounts where display_name='Synthetic location bank'),'cash',null,60000,'Synthetic disbursement funds');
create temp table test_loan as select id from public.create_loan_contract('a2010000-0000-4000-8000-000000000003','location-loan','a2010000-0000-4000-8000-000000000004',null,null,60000,'fixed_interest','MONTHLY_FIXED',0.05,2,'2026-08-01');
select public.confirm_loan_disbursement((select id from test_loan),'location-disbursement','2026-08-01');
select public.record_loan_payment((select id from test_loan),'location-payment-one','2026-10-10',11500,10000,1500,'regular');
select public.reverse_financial_operation((select operation_id from loan_payments where idempotency_key='location-payment-one'),'location-payment-undo','2026-10-16','Synthetic mistaken duplicate');
select public.record_loan_payment((select id from test_loan),'location-payment-two','2026-10-15',11500,10000,1500,'regular');
create temp table source_payments as select to_jsonb(p)row from loan_payments p where loan_id=(select id from test_loan);
create temp table source_accounts as select account,sum(amount)amount from ledger_entries where cycle_id='a2010000-0000-4000-8000-000000000003'group by account;
select lives_ok($$select public.correct_cash_loan_location((select operation_id from loan_payments where idempotency_key='location-payment-one'),(select id from bank_accounts where display_name='Synthetic location bank'),'location-correction-one','Confirmed direct bank receipt')$$,'corrects original and already posted annulment atomically');
select is((select count(*)from financial_operations where operation_type='cash_location_corrected'and cycle_id='a2010000-0000-4000-8000-000000000003'),2::bigint,'one dated classification for each original and annulment');
select is((select sum(e.amount)from ledger_entries e join financial_operations o on o.id=e.operation_id where e.cycle_id='a2010000-0000-4000-8000-000000000003'and e.account='cash'and e.liquidity_location='cash'and o.effective_date<='2026-10-15'),11500::numeric,'historical cash of reversed payment corrected without moving later receipt');
select lives_ok($$select public.correct_cash_loan_location((select operation_id from loan_payments where idempotency_key='location-payment-two'),(select id from bank_accounts where display_name='Synthetic location bank'),'location-correction-two','Confirmed direct bank receipt')$$,'corrects active receipt without another payment');
select is((select sum(e.amount)from ledger_entries e join financial_operations o on o.id=e.operation_id where e.cycle_id='a2010000-0000-4000-8000-000000000003'and e.account='cash'and e.liquidity_location='cash'and o.effective_date<='2026-10-15'),0::numeric,'cash at statement cut becomes exactly zero');
select is((select sum(amount)from ledger_entries where cycle_id='a2010000-0000-4000-8000-000000000003'and account='cash'and liquidity_location='cash'),0::numeric,'cash today also exactly zero after dated annulment');
select is((select sum(amount)from ledger_entries where cycle_id='a2010000-0000-4000-8000-000000000003'and account='cash'and liquidity_location='bank'),951500::numeric,'bank includes only net real receipt');
select is((select count(*)from source_accounts b full join(select account,sum(amount)amount from ledger_entries where cycle_id='a2010000-0000-4000-8000-000000000003'group by account)a on a.account=b.account where a.amount is distinct from b.amount),0::bigint,'every financial account total unchanged');
select is((select count(*)from loan_payments p where loan_id=(select id from test_loan)and not exists(select 1 from source_payments b where b.row=to_jsonb(p))),0::bigint,'original payments and statuses remain byte-equivalent');
select lives_ok($$select public.correct_cash_loan_location((select operation_id from loan_payments where idempotency_key='location-payment-one'),(select id from bank_accounts where display_name='Synthetic location bank'),'location-correction-one','Confirmed direct bank receipt')$$,'correction exact retry is idempotent');
select throws_ok($$select public.correct_cash_loan_location((select operation_id from loan_payments where idempotency_key='location-payment-one'),(select id from bank_accounts where display_name='Synthetic location bank'),'location-correction-one','Changed reason')$$,null,null,'changed correction retry rejected');
select throws_ok($$select public.correct_cash_loan_location((select operation_id from loan_payments where idempotency_key='location-payment-one'),(select id from bank_accounts where display_name='Synthetic location bank'),'location-correction-new','Confirmed direct bank receipt')$$,null,null,'another key cannot classify the same receipt twice');
select throws_ok($$select public.reverse_financial_operation((select operation_id from loan_payments where idempotency_key='location-payment-two'),'location-payment-undo-two','2026-10-20','Synthetic correction')$$,null,null,'payment annulment requires resolving location correction first');
select throws_ok($$select public.reverse_financial_operation((select id from financial_operations where idempotency_key='location-correction-one'),'location-split-undo','2026-10-20','Synthetic correction')$$,null,null,'partial correction annulment forbidden');
select lives_ok($$select public.annul_cash_loan_location((select operation_id from loan_payments where idempotency_key='location-payment-one'),'location-correction-undo','Synthetic correction')$$,'group annulment restores original classifications and dates');
select lives_ok($$select public.annul_cash_loan_location((select operation_id from loan_payments where idempotency_key='location-payment-one'),'location-correction-undo','Synthetic correction')$$,'group annulment exact retry idempotent');
select is((select sum(e.amount)from ledger_entries e join financial_operations o on o.id=e.operation_id where e.cycle_id='a2010000-0000-4000-8000-000000000003'and e.account='cash'and e.liquidity_location='cash'and o.effective_date<='2026-10-15'),11500::numeric,'undo restores historical cash without falsifying total');
select lives_ok($$select public.correct_cash_loan_location((select operation_id from loan_payments where idempotency_key='location-payment-one'),(select id from bank_accounts where display_name='Synthetic location bank'),'location-correction-again','Reconfirmed direct bank receipt')$$,'can correct again after full annulment');
select lives_ok($$select public.annul_cash_loan_location((select operation_id from loan_payments where idempotency_key='location-payment-one'),'location-correction-undo-again','New synthetic correction')$$,'new annulment touches only latest correction group');
select lives_ok($$select public.annul_cash_loan_location((select operation_id from loan_payments where idempotency_key='location-payment-one'),'location-correction-undo','Synthetic correction')$$,'retry of older annulment does not consume later group');
savepoint located_payment;
select lives_ok($$select public.record_located_loan_payment((select id from test_loan),'located-new-receipt','2026-10-20',11500,10000,1500,'regular',(select id from bank_accounts where display_name='Synthetic location bank'),null)$$,'new receipt goes to selected bank in the payment transaction');
-- A single pgTAP transaction gives now() to every receipt. Model the known distinct RPC order explicitly.
reset role;
update public.loan_payments set created_at='2026-10-20T12:00:00Z' where idempotency_key='located-new-receipt';
set local role authenticated;
select is((select sum(e.amount)from ledger_entries e join financial_operations o on o.id=e.operation_id where e.cycle_id='a2010000-0000-4000-8000-000000000003'and e.account='cash'and e.liquidity_location='cash'),0::numeric,'new bank receipt never leaves physical cash behind');
select is((select count(*)from loan_payments where idempotency_key='located-new-receipt'),1::bigint,'selected location creates one domain payment');
select lives_ok($$select public.record_located_loan_payment((select id from test_loan),'located-new-receipt','2026-10-20',11500,10000,1500,'regular',(select id from bank_accounts where display_name='Synthetic location bank'),null)$$,'located receipt exact retry idempotent');
select throws_ok($$select public.record_located_loan_payment((select id from test_loan),'located-new-receipt','2026-10-20',11500,10000,1500,'regular',null,null)$$,'P0001','El destino del cobro no coincide con el intento original.','retry cannot move money to a different destination');
savepoint located_undo;
select lives_ok($$select public.reverse_financial_operation((select operation_id from loan_payments where idempotency_key='located-new-receipt'),'located-new-undo','2026-10-20','Synthetic mistaken receipt')$$,'one annul action reverses new bank receipt and its destination atomically');
select is((select sum(amount)from ledger_entries where cycle_id='a2010000-0000-4000-8000-000000000003'and account='cash'and liquidity_location='cash'),0::numeric,'annulling bank receipt does not restore fictitious cash');
select is((select sum(amount)from ledger_entries where cycle_id='a2010000-0000-4000-8000-000000000003'and account='cash'and liquidity_location='bank'),951500::numeric,'bank returns exactly to balance before receipt');
select lives_ok($$select public.reverse_financial_operation((select operation_id from loan_payments where idempotency_key='located-new-receipt'),'located-new-undo','2026-10-20','Synthetic mistaken receipt')$$,'bank receipt annulment exact retry idempotent');
rollback to located_undo;
create temp table destination_quote as select public.quote_loan_prepayment((select id from test_loan),'2026-10-20')q;
select lives_ok($$select public.record_located_loan_payment((select id from test_loan),'located-full-receipt','2026-10-20',null,null,null,'prepayment',(select id from bank_accounts where display_name='Synthetic location bank'),(select q->>'quote_hash'from destination_quote))$$,'quoted full payment keeps existing policy and selected bank');
reset role;
update public.loan_payments set created_at='2026-10-20T12:01:00Z' where idempotency_key='located-full-receipt';
set local role authenticated;
select is((select status from loan_contracts where id=(select id from test_loan)),'paid','located prepayment still closes loan and applications');
select lives_ok($$select public.record_located_loan_payment((select id from test_loan),'located-full-receipt','2026-10-20',null,null,null,'prepayment',(select id from bank_accounts where display_name='Synthetic location bank'),(select q->>'quote_hash'from destination_quote))$$,'prepayment exact retry after loan paid returns same receipt');
select lives_ok($$select public.reverse_financial_operation((select operation_id from loan_payments where idempotency_key='located-full-receipt'),'located-full-undo','2026-10-20','Synthetic full payment correction')$$,'full bank repayment can also be annulled in one action');
select is((select status from loan_contracts where id=(select id from test_loan)),'active','annulling full repayment reopens loan');
select is((select sum(amount)from ledger_entries where cycle_id='a2010000-0000-4000-8000-000000000003'and account='cash'and liquidity_location='bank'),963000::numeric,'annulled full repayment restores bank exactly');
select is((select sum(amount)from ledger_entries where cycle_id='a2010000-0000-4000-8000-000000000003'and account='cash'and liquidity_location='cash'),0::numeric,'annulled full repayment never creates fictitious cash');
rollback to located_payment;
select is((select count(*)from(select operation_id from ledger_entries where cycle_id='a2010000-0000-4000-8000-000000000003'group by 1 having sum(amount)<>0)x),0::bigint,'all correction and annulment operations balance');
reset role;
select ok(not has_function_privilege('anon','public.record_settlement_completion(uuid,text,date,numeric,uuid,text,date,numeric,numeric,numeric,text)','EXECUTE'),'anonymous completion forbidden');
select ok(not has_function_privilege('anon','public.record_located_loan_payment(uuid,text,date,numeric,numeric,numeric,text,uuid,text)','EXECUTE'),'anonymous located payment forbidden');
select ok(not has_function_privilege('authenticated','public.completion_confirm_base(uuid,text,date,numeric,numeric,numeric,text)','EXECUTE'),'cannot bypass guarded confirmation');
select ok(not has_function_privilege('authenticated','public.completion_reverse_base(uuid,text,date,text)','EXECUTE'),'cannot bypass reversal dependencies');
select * from finish();
rollback;
